// Configuration initiale
const config = {
  // Configuration du fichier (À CONFIGURER)
  documentId: 'YOUR_GOOGLE_SHEET_ID',  // ID du Google Sheet
  sheetName: 'Audit_Data',              // Nom de la feuille

  // Configuration LLM
  model: 'gpt-4o',
  temperature: 0.3,
  maxTokens: 800,

  // Paramètres de traitement
  batchSize: 10,
  retryAttempts: 3,

  // Configuration email
  emailTo: 'qualite@entreprise.com',  // À CONFIGURER

  // Colonnes du fichier
  columns: {
    id: 'ID',
    exigence: 'NumeroExigence',
    constat: 'Constat',
    scope: 'Scope',
    analyse: 'Analyse_IA',
    status: 'Status_Traitement',
    date: 'Date_Analyse',
    criticite: 'Criticite',
    scoreRisque: 'Score_Risque'
  }
};

return [{
  json: { config }
}];

// Filtrer les lignes qui nécessitent une analyse IA
const allItems = $input.all();
const config = $node["Initialize Config"].json.config;

const processedItems = [];
let rowIndex = 1; // Commencer à 1 car ligne 0 est l'en-tête

for (const item of allItems) {
  rowIndex++;

  // Vérifier si la ligne doit être traitée
  const needsProcessing = !item.json[config.columns.analyse] || 
                         item.json[config.columns.status] === 'À retraiter';

  if (needsProcessing && item.json[config.columns.constat]) {
    processedItems.push({
      json: {
        ...item.json,
        needsAI: true,
        originalIndex: rowIndex,
        rowNumber: rowIndex
      }
    });
  } else {
    processedItems.push({
      json: {
        ...item.json,
        needsAI: false,
        originalIndex: rowIndex,
        rowNumber: rowIndex
      }
    });
  }
}

return processedItems;

// Créer des lots pour le traitement
const allItems = $input.all();
const config = $node["Initialize Config"].json.config;

// Filtrer uniquement les items qui nécessitent l'IA
const itemsNeedingAI = allItems.filter(item => item.json.needsAI);

if (itemsNeedingAI.length === 0) {
  return [{
    json: {
      hasBatches: false,
      message: 'Aucune ligne à traiter',
      allItems: allItems
    }
  }];
}

// Créer les lots
const batchSize = config.batchSize;
const batches = [];

for (let i = 0; i < itemsNeedingAI.length; i += batchSize) {
  const batch = itemsNeedingAI.slice(i, i + batchSize);
  batches.push({
    json: {
      batchId: Math.floor(i / batchSize) + 1,
      totalBatches: Math.ceil(itemsNeedingAI.length / batchSize),
      items: batch.map(item => item.json),
      timestamp: new Date().toISOString(),
      hasBatches: true
    }
  });
}

return batches;

// Construire le prompt pour l'IA
const item = $json;
const config = $node["Initialize Config"].json.config;

// Si pas de batch, passer au suivant
if (!item.hasBatches) {
  return [{ json: item }];
}

// Traiter chaque item du batch
const results = [];

for (const dataItem of item.items) {
  const systemPrompt = `Tu es un expert auditeur IFS Food v8 avec 15 ans d'expérience.

MISSION: Analyser le constat d'audit et fournir une évaluation structurée.

FORMAT DE RÉPONSE OBLIGATOIRE:
1. CRITICITÉ: [Critique/Majeure/Mineure]
2. RISQUES: [Liste des risques identifiés]
3. EXIGENCES IFS: [Références précises aux clauses IFS Food v8]
4. RECOMMANDATIONS: [Actions correctives détaillées]
5. DÉLAI: [Court terme/Moyen terme/Long terme]

Réponds en français et de manière structurée.`;

  const userPrompt = `DONNÉES D'AUDIT:
- Exigence n°: ${dataItem[config.columns.exigence] || 'Non spécifiée'}
- Scope: ${dataItem[config.columns.scope] || 'Non spécifié'}
- Constat: ${dataItem[config.columns.constat]}

Analyse ce constat selon les standards IFS Food v8.`;

  results.push({
    json: {
      ...dataItem,
      systemPrompt: systemPrompt,
      userPrompt: userPrompt,
      batchId: item.batchId
    }
  });
}

return results;

// Parser et valider la réponse de l'IA
const item = $json;
const config = $node["Initialize Config"].json.config;

// Vérifier si l'appel OpenAI a réussi
if (!item.message || !item.message.content) {
  return [{
    json: {
      ...item,
      [config.columns.analyse]: 'ERREUR: Analyse non disponible',
      [config.columns.status]: 'Échec',
      [config.columns.date]: new Date().toISOString(),
      [config.columns.criticite]: '',
      [config.columns.scoreRisque]: 0,
      error: 'Échec de l\'appel OpenAI'
    }
  }];
}

const aiResponse = item.message.content;

// Parser la réponse pour extraire les éléments structurés
function parseAIResponse(response) {
  const result = {
    criticite: '',
    risques: [],
    exigences: [],
    recommandations: [],
    delai: ''
  };

  try {
    // Extraction de la criticité
    const criticiteMatch = response.match(/CRITICITÉ:\s*\[([^\]]+)\]/i);
    if (criticiteMatch) {
      result.criticite = criticiteMatch[1].trim();
    } else {
      // Recherche alternative
      if (response.toLowerCase().includes('critique')) result.criticite = 'Critique';
      else if (response.toLowerCase().includes('majeure')) result.criticite = 'Majeure';
      else if (response.toLowerCase().includes('mineure')) result.criticite = 'Mineure';
    }

    // Extraction des risques
    const risquesMatch = response.match(/RISQUES:\s*\[([^\]]+)\]/i);
    if (risquesMatch) {
      result.risques = risquesMatch[1].split(',').map(r => r.trim());
    }

  } catch (e) {
    console.error('Parsing error:', e);
  }

  return result;
}

const parsed = parseAIResponse(aiResponse);

// Calculer le score de risque
function calculateRiskScore(parsed) {
  const scores = {
    'Critique': 10,
    'Majeure': 7,
    'Mineure': 3
  };
  return scores[parsed.criticite] || 5;
}

return [{
  json: {
    ...item,
    [config.columns.analyse]: aiResponse,
    [config.columns.status]: 'Complété',
    [config.columns.date]: new Date().toISOString(),
    [config.columns.criticite]: parsed.criticite,
    [config.columns.scoreRisque]: calculateRiskScore(parsed)
  }
}];

// Fusionner tous les résultats
const allOriginalItems = $node["Filter Rows"].all();
const processedItems = $input.all();
const config = $node["Initialize Config"].json.config;

// Créer un map pour un accès rapide par numéro de ligne
const processedMap = new Map();
processedItems.forEach(item => {
  if (item.json.rowNumber) {
    processedMap.set(item.json.rowNumber, item.json);
  }
});

// Reconstruire le dataset complet
const finalData = [];
let processedCount = 0;
let successCount = 0;
let errorCount = 0;

for (const original of allOriginalItems) {
  const processed = processedMap.get(original.json.rowNumber);

  if (processed && original.json.needsAI) {
    // Fusionner les données traitées
    finalData.push({
      json: {
        ...original.json,
        [config.columns.analyse]: processed[config.columns.analyse],
        [config.columns.status]: processed[config.columns.status],
        [config.columns.date]: processed[config.columns.date],
        [config.columns.criticite]: processed[config.columns.criticite],
        [config.columns.scoreRisque]: processed[config.columns.scoreRisque]
      }
    });
    processedCount++;
    if (processed[config.columns.status] === 'Complété') successCount++;
    if (processed[config.columns.status] === 'Échec') errorCount++;
  } else {
    // Garder les données originales
    finalData.push(original);
  }
}

// Calculer les statistiques
const stats = {
  totalRows: allOriginalItems.length,
  processedRows: processedCount,
  successRows: successCount,
  errorRows: errorCount,
  successRate: processedCount > 0 ? ((successCount / processedCount) * 100).toFixed(1) : 0
};

// Compter par criticité
const criticiteCounts = {
  Critique: 0,
  Majeure: 0,
  Mineure: 0
};

finalData.forEach(item => {
  const crit = item.json[config.columns.criticite];
  if (crit && criticiteCounts.hasOwnProperty(crit)) {
    criticiteCounts[crit]++;
  }
});

stats.criticiteCounts = criticiteCounts;

return [{
  json: {
    data: finalData.map(item => item.json),
    stats: stats,
    timestamp: new Date().toISOString()
  }
}];

// Générer le rapport d'analyse
const mergedData = $node["Merge Results"].json;
const stats = mergedData.stats;
const config = $node["Initialize Config"].json.config;

const report = `
📊 RAPPORT D'ANALYSE IFS FOOD
═══════════════════════════════════════

Date: ${new Date().toLocaleDateString('fr-FR', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
})}

✅ RÉSULTATS DU TRAITEMENT
─────────────────────────────────────
• Lignes totales: ${stats.totalRows}
• Lignes analysées: ${stats.processedRows}
• Succès: ${stats.successRows}
• Échecs: ${stats.errorRows}
• Taux de réussite: ${stats.successRate}%

🎯 RÉPARTITION PAR CRITICITÉ
─────────────────────────────────────
• 🔴 Critique: ${stats.criticiteCounts.Critique}
• 🟠 Majeure: ${stats.criticiteCounts.Majeure}
• 🟡 Mineure: ${stats.criticiteCounts.Mineure}

📝 ACTIONS REQUISES
─────────────────────────────────────
${stats.criticiteCounts.Critique > 0 ? '⚠️  URGENT: ' + stats.criticiteCounts.Critique + ' constat(s) critique(s) nécessitent une action immédiate' : '✓ Aucun constat critique'}
${stats.criticiteCounts.Majeure > 0 ? '• ' + stats.criticiteCounts.Majeure + ' constat(s) majeur(s) à traiter rapidement' : ''}
${stats.criticiteCounts.Mineure > 0 ? '• ' + stats.criticiteCounts.Mineure + ' constat(s) mineur(s) à planifier' : ''}

🔗 ACCÈS AU FICHIER
─────────────────────────────────────
Google Sheets: https://docs.google.com/spreadsheets/d/${config.documentId}

═══════════════════════════════════════
Généré automatiquement par n8n
`;

return [{
  json: {
    report: report,
    stats: stats,
    emailSubject: `[IFS Food] Rapport d'analyse - ${stats.successRows}/${stats.processedRows} constats traités`,
    timestamp: new Date().toISOString()
  }
}];
